out_file = os.path.join(os.path.dirname(__file__), "quiz_data_hills_beaches.py")
with open(out_file, "w", encoding="utf-8") as f:
    f.write('"""Bhromon Quiz Engine — Hills, Treks, Beaches & Islands Questions.\n\n')
    f.write('220 Unique, authentic, verified questions on trekking, peaks, waterfalls, and ocean destinations.\n"""\n\n')
    f.write('from typing import List, Dict, Any\n\n')
    f.write('HILLS_BEACHES_QUESTIONS: List[Dict[str, Any]] = [\n')
    for item in QUESTIONS:
        f.write("    " + repr(item) + ",\n")
    f.write("]\n")

